    private static final int MIN_DEPTH = 4;
    private static final int TARGET_NODES_PER_TASK = 1 << 18;
    private static final int MAX_TREES_PER_TASK = 4096;

    public static void main(String[] args) {
        int n = Integer.parseInt(args[0]);

        int maxDepth = n;
        int stretchDepth = maxDepth + 1;

        StringBuilder out = new StringBuilder();

        out.append("stretch tree of depth ")
           .append(stretchDepth)
           .append("\t check: ")
           .append(bottomUpTree(stretchDepth).itemCheck())
           .append('\n');

        TreeNode longLivedTree = bottomUpTree(maxDepth);

        ForkJoinPool pool = new ForkJoinPool();

        for (int depth = MIN_DEPTH; depth <= maxDepth; depth += 2) {
            long iterations = 1L << (maxDepth - depth + MIN_DEPTH);
            int taskSize = taskSizeForDepth(depth);

            long check = pool.invoke(new CheckTask(depth, 0, iterations, taskSize));

            out.append(iterations)
               .append("\t trees of depth ")
               .append(depth)
               .append("\t check: ")
               .append(check)
               .append('\n');
        }

        pool.shutdown();

        out.append("long lived tree of depth ")
           .append(maxDepth)
           .append("\t check: ")
           .append(longLivedTree.itemCheck())
           .append('\n');

        System.out.print(out.toString());
    }

    private static int taskSizeForDepth(int depth) {
        long nodesPerTree;
        if (depth >= 62) {
            nodesPerTree = Long.MAX_VALUE;
        } else {
            nodesPerTree = (1L << (depth + 1)) - 1L;
        }

